"use strict";(self.webpackChunkpa_openapi_docs=self.webpackChunkpa_openapi_docs||[]).push([[1620],{9651:e=>{e.exports=JSON.parse('{"blogPosts":[{"id":"2026-05-27-update","metadata":{"permalink":"/openapi-guide/blog/2026-05-27-update","source":"@site/blog/2026-05-27-update/index.md","title":"2026\ub144 5\uc6d4 \ud50c\ub7ab\ud3fc \ubcc0\uacbd \uc0ac\ud56d \uc548\ub0b4 (5\uc6d4 27\uc77c \uc5c5\ub370\uc774\ud2b8)","description":"\uc548\ub155\ud558\uc138\uc694. \ub124\uc774\ubc84 \uc131\uacfc\ud615 \ub514\uc2a4\ud50c\ub808\uc774 \uad11\uace0 \uc624\ud508 API \uc6b4\uc601\uc790\uc785\ub2c8\ub2e4.","date":"2026-05-27T00:00:00.000Z","formattedDate":"2026\ub144 5\uc6d4 27\uc77c","tags":[{"label":"patch","permalink":"/openapi-guide/blog/tags/patch"}],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"2026-05-27-update","title":"2026\ub144 5\uc6d4 \ud50c\ub7ab\ud3fc \ubcc0\uacbd \uc0ac\ud56d \uc548\ub0b4 (5\uc6d4 27\uc77c \uc5c5\ub370\uc774\ud2b8)","tags":["patch"]},"nextItem":{"title":"2025\ub144 4\uc6d4 \ud50c\ub7ab\ud3fc \ubcc0\uacbd \uc0ac\ud56d \uc548\ub0b4 (4\uc6d4 24\uc77c \uc5c5\ub370\uc774\ud2b8)","permalink":"/openapi-guide/blog/2025-04-24-update"}},"content":"\uc548\ub155\ud558\uc138\uc694. \ub124\uc774\ubc84 \uc131\uacfc\ud615 \ub514\uc2a4\ud50c\ub808\uc774 \uad11\uace0 \uc624\ud508 API \uc6b4\uc601\uc790\uc785\ub2c8\ub2e4.\\n\\n2026\ub144 5\uc6d4 \ub124\uc774\ubc84 \uc131\uacfc\ud615 \ub514\uc2a4\ud50c\ub808\uc774 \uad11\uace0 \ud50c\ub7ab\ud3fc \ubcc0\uacbd \uc0ac\ud56d \uc548\ub0b4\ub4dc\ub9bd\ub2c8\ub2e4.\\n\uc790\uc138\ud55c \uc0ac\ud56d\uc740 \uc544\ub798 \ub0b4\uc6a9\uc744 \ucc38\uace0\ud558\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.\u200b\\n\\n**\u25a0 \ubcc0\uacbd \uc0ac\ud56d**\\n\\n[1] \uad11\uace0 \uc18c\uc7ac \uc0dd\uc131 API \uc2e0\uaddc \uc81c\uacf5\\n\\n[2] \uad11\uace0 \uc18c\uc7ac \uc5d0\uc14b(\uc774\ubbf8\uc9c0/\ub3d9\uc601\uc0c1) \uc5c5\ub85c\ub4dc API \uc2e0\uaddc \uc81c\uacf5\\n\\n**\u25a0 \uc0c1\uc138 \ubcc0\uacbd \ub0b4\uc6a9**\\n\\n[1] \uad11\uace0 \uc18c\uc7ac \uc0dd\uc131 API \uc2e0\uaddc \uc81c\uacf5\\n\\n\uadf8\ub3d9\uc548 \ub124\uc774\ubc84 \uc131\uacfc\ud615 \ub514\uc2a4\ud50c\ub808\uc774 \uad11\uace0 \uc0ac\uc774\ud2b8\ub97c \ud1b5\ud574\uc11c\ub9cc \uac00\ub2a5\ud588\ub358 \uad11\uace0 \uc18c\uc7ac \uc0dd\uc131\uc744 \uc624\ud508 API\ub85c \uc9c1\uc811 \uc218\ud589\ud560 \uc218 \uc788\ub3c4\ub85d \uae30\ub2a5\uc744 \ud655\uc7a5\ud569\ub2c8\ub2e4. \uad11\uace0 \uadf8\ub8f9\uc758 \uc18c\uc7ac \ud0c0\uc785(`creativeType`) \ubc0f \uc18c\uc7ac \ud15c\ud50c\ub9bf(`creativeTemplateCode`)\uc5d0 \ub530\ub77c \uc544\ub798\uc640 \uac19\uc774 \ub2e4\uc591\ud55c \ud615\ud0dc\uc758 \uc18c\uc7ac \uc0dd\uc131\uc744 \uc9c0\uc6d0\ud569\ub2c8\ub2e4.\\n\\n- \uc774\ubbf8\uc9c0 \ubc30\ub108\ud615 \uc18c\uc7ac (\uc2a4\ub9c8\ud2b8\ucc44\ub110 / \ubaa8\ubc14\uc77cDA) \uc0dd\uc131 API\\n- \ub124\uc774\ud2f0\ube0c \uc774\ubbf8\uc9c0 \uc18c\uc7ac (\ud53c\ub4dc\ud615 / \ubc30\ub108\ud615) \uc0dd\uc131 API\\n  - \uc9c0\uc6d0 \ud15c\ud50c\ub9bf: `NATIVE_SINGLE_IMAGE_V2`, `NATIVE_SINGLE_IMAGE_PC`, `FEED_SINGLE_IMAGE`, `FEED_SINGLE_IMAGE_SQUARE`, `FEED_SINGLE_IMAGE_2TO3`, `NATIVE_SINGLE_IMAGE_COMMUNICATION`\\n- \uceec\ub809\uc158 \uc18c\uc7ac (\uc774\ubbf8\uc9c0 \uceec\ub809\uc158 / \ub3d9\uc601\uc0c1 \uceec\ub809\uc158) \uc0dd\uc131 API\\n- \ub3d9\uc601\uc0c1 \uc18c\uc7ac (\ud53c\ub4dc\ud615 / \ubc30\ub108\ud615 / \uc778\uc2a4\ud2b8\ub9bc) \uc0dd\uc131 API\\n  - \uc9c0\uc6d0 \ud15c\ud50c\ub9bf: `NATIVE_SINGLE_VIDEO`, `FEED_SHORTFORM_VIDEO`, `FEED_SINGLE_VIDEO`, `INSTREAM_VIDEO`\\n\\n> \ub124\uc774\ud2f0\ube0c \uc774\ubbf8\uc9c0 / \uceec\ub809\uc158 / \ub3d9\uc601\uc0c1 \uc18c\uc7ac \uc0dd\uc131\uc744 \uc704\ud574\uc11c\ub294 \uc0ac\uc804\uc5d0 `\uad11\uace0 \uacc4\uc815 \uad00\ub9ac > \ud504\ub85c\ud544 \uad00\ub9ac`\uc5d0\uc11c \ud504\ub85c\ud544 \ub4f1\ub85d\uc774 \ud544\uc694\ud569\ub2c8\ub2e4. \uc790\uc138\ud55c \ud15c\ud50c\ub9bf\ubcc4 \ud544\uc218/\uc120\ud0dd \ud30c\ub77c\ubbf8\ud130\ub294 [\uad11\uace0 \uc18c\uc7ac \uac00\uc774\ub4dc](/docs/ad-management/creative) \ubb38\uc11c\ub97c \ucc38\uace0\ud574 \uc8fc\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.\\n\\n[2] \uad11\uace0 \uc18c\uc7ac \uc5d0\uc14b(\uc774\ubbf8\uc9c0/\ub3d9\uc601\uc0c1) \uc5c5\ub85c\ub4dc API \uc2e0\uaddc \uc81c\uacf5\\n\\n\uad11\uace0 \uc18c\uc7ac \uc0dd\uc131\uc5d0 \uc0ac\uc6a9\ud560 \uc774\ubbf8\uc9c0\xb7\ub3d9\uc601\uc0c1 \ud30c\uc77c\uc744 \uc0ac\uc804\uc5d0 \uc5c5\ub85c\ub4dc\ud560 \uc218 \uc788\ub294 \uc804\uc6a9 API\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4. \uc5c5\ub85c\ub4dc \uc751\ub2f5\uc73c\ub85c \ubc1b\uc740 ID \uac12\uc744 \uc18c\uc7ac \uc0dd\uc131 API\uc758 `imageNo`, `videoNo`, `thumbnailImageNo` \ub4f1 \ud30c\ub77c\ubbf8\ud130\uc5d0 \uadf8\ub300\ub85c \uc0ac\uc6a9\ud558\uc2dc\uba74 \ub429\ub2c8\ub2e4.\\n\\n- \uc774\ubbf8\uc9c0 \uc5c5\ub85c\ub4dc API\\n- \ub3d9\uc601\uc0c1 \uc5c5\ub85c\ub4dc API\\n  - \uad11\uace0 \uacc4\uc815\ub2f9 \ub3d9\uc2dc\uc5d0 1\ud68c \ud638\ucd9c\uc774 \uac00\ub2a5\ud569\ub2c8\ub2e4.\\n  - \ub3d9\uc601\uc0c1 \ud30c\uc77c\uc740 100MB \uc774\ub0b4\uae4c\uc9c0 \uc5c5\ub85c\ub4dc \uac00\ub2a5\ud558\uba70, \uadf8 \uc774\uc0c1\uc740 \ub124\uc774\ubc84 \uc131\uacfc\ud615 \ub514\uc2a4\ud50c\ub808\uc774 \uad11\uace0 \uc0ac\uc774\ud2b8\ub97c \ud1b5\ud574 \uc9c1\uc811 \uc5c5\ub85c\ub4dc\ud574 \uc8fc\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.\\n  - \uc5c5\ub85c\ub4dc/\uc778\ucf54\ub529 \uc644\ub8cc \ubc0f \uc2e4\ud328 \uc2dc\uc810\uc744 \uc218\uc2e0\ud560 \uc218 \uc788\ub3c4\ub85d `callbackUrl` \ub4f1\ub85d\uc744 \uc9c0\uc6d0\ud569\ub2c8\ub2e4.\\n\\n**\uc801\uc6a9 \uc77c\uc790**\\n\\n2026\ub144 5\uc6d4 27\uc77c \uc218\uc694\uc77c\\n\\n**\ubcc0\uacbd \uc0ac\ud56d**\\n\\n- \uad11\uace0 \uc18c\uc7ac \uc0dd\uc131 API \ucd94\uac00\\n  - \uc774\ubbf8\uc9c0 \ubc30\ub108\ud615 / \ub124\uc774\ud2f0\ube0c \uc774\ubbf8\uc9c0 / \uceec\ub809\uc158 / \ub3d9\uc601\uc0c1(\ud53c\ub4dc\xb7\ubc30\ub108\xb7\uc778\uc2a4\ud2b8\ub9bc) \uc18c\uc7ac \uc0dd\uc131 API \uc2e0\uaddc \uc81c\uacf5\\n  - \ub124\uc774\ud2f0\ube0c \uc774\ubbf8\uc9c0 \uc2e0\uaddc \ud15c\ud50c\ub9bf `NATIVE_SINGLE_IMAGE_COMMUNICATION` \ucd94\uac00\\n- \uad11\uace0 \uc18c\uc7ac \uc5d0\uc14b \uc5c5\ub85c\ub4dc API \ucd94\uac00\\n  - \uc774\ubbf8\uc9c0 \uc5c5\ub85c\ub4dc / \ub3d9\uc601\uc0c1 \uc5c5\ub85c\ub4dc (\ucf5c\ubc31 \uc9c0\uc6d0) API \uc2e0\uaddc \uc81c\uacf5\\n\\n\uae30\ud0c0 \uad81\uae08\ud558\uc2e0 \uc0ac\ud56d\uc740 \ub124\uc774\ubc84 \uc131\uacfc\ud615 \ub514\uc2a4\ud50c\ub808\uc774 \uad11\uace0 API \ubb38\uc758\ub97c \uc774\uc6a9\ud574 \uc8fc\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.\\n\\n\uac10\uc0ac\ud569\ub2c8\ub2e4."},{"id":"2025-04-24-update","metadata":{"permalink":"/openapi-guide/blog/2025-04-24-update","source":"@site/blog/2025-04-24-update/index.md","title":"2025\ub144 4\uc6d4 \ud50c\ub7ab\ud3fc \ubcc0\uacbd \uc0ac\ud56d \uc548\ub0b4 (4\uc6d4 24\uc77c \uc5c5\ub370\uc774\ud2b8)","description":"\uc548\ub155\ud558\uc138\uc694. \ub124\uc774\ubc84 \uc131\uacfc\ud615 \ub514\uc2a4\ud50c\ub808\uc774 \uad11\uace0 \uc624\ud508 API \uc6b4\uc601\uc790\uc785\ub2c8\ub2e4.","date":"2025-04-24T00:00:00.000Z","formattedDate":"2025\ub144 4\uc6d4 24\uc77c","tags":[{"label":"patch","permalink":"/openapi-guide/blog/tags/patch"}],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"2025-04-24-update","title":"2025\ub144 4\uc6d4 \ud50c\ub7ab\ud3fc \ubcc0\uacbd \uc0ac\ud56d \uc548\ub0b4 (4\uc6d4 24\uc77c \uc5c5\ub370\uc774\ud2b8)","tags":["patch"]},"prevItem":{"title":"2026\ub144 5\uc6d4 \ud50c\ub7ab\ud3fc \ubcc0\uacbd \uc0ac\ud56d \uc548\ub0b4 (5\uc6d4 27\uc77c \uc5c5\ub370\uc774\ud2b8)","permalink":"/openapi-guide/blog/2026-05-27-update"},"nextItem":{"title":"2025\ub144 3\uc6d4 \ud50c\ub7ab\ud3fc \ubcc0\uacbd \uc0ac\ud56d \uc548\ub0b4 (3\uc6d4 14\uc77c \uc5c5\ub370\uc774\ud2b8)","permalink":"/openapi-guide/blog/2025-03-14-update"}},"content":"\uc548\ub155\ud558\uc138\uc694. \ub124\uc774\ubc84 \uc131\uacfc\ud615 \ub514\uc2a4\ud50c\ub808\uc774 \uad11\uace0 \uc624\ud508 API \uc6b4\uc601\uc790\uc785\ub2c8\ub2e4.\\n\\n2025\ub144 4\uc6d4 \ub124\uc774\ubc84 \uc131\uacfc\ud615 \ub514\uc2a4\ud50c\ub808\uc774 \uad11\uace0 \ud50c\ub7ab\ud3fc \ubcc0\uacbd \uc0ac\ud56d \uc548\ub0b4\ub4dc\ub9bd\ub2c8\ub2e4.  \\n\uc790\uc138\ud55c \uc0ac\ud56d\uc740 \uc544\ub798 \ub0b4\uc6a9\uc744 \ucc38\uace0\ud558\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.\\n\\n**\u25a0 \ubcc0\uacbd \uc0ac\ud56d**  \\n\\n[1] \uc131\uacfc \uc870\ud68c \uc751\ub2f5 \ub0b4 \'convPartner\' \uac12 \uc81c\uac70  \\n[2] \ucea0\ud398\uc778 \uc608\uc0b0 \ub2e4\uc911 \ubcc0\uacbd \'Deprecated\' \ucc98\ub9ac\\n\\n**\u25a0 \uc0c1\uc138 \ubcc0\uacbd \ub0b4\uc6a9**\\n\\n[1] \uc131\uacfc \uc870\ud68c \uc751\ub2f5 \ub0b4 \'convPartner\' \uac12 \uc81c\uac70  \\n\uacfc\uac70 \uc804\ud658 \uc131\uacfc \uc870\ud68c \ubc0f \uc2e4\uc2dc\uac04 \uc804\ud658 \uc131\uacfc \uc870\ud68c \uc751\ub2f5 \ub0b4 \ud56d\ubaa9\uc73c\ub85c \uc81c\uacf5\ub418\uc5c8\uc73c\ub098,  \\n\uc0c1\ud669\uc0c1 \uba85\ud655\ud55c \uad6c\ubd84\uc774 \uc5b4\ub824\uc6cc \ud574\ub2f9 \uac12\uc758 \uc81c\uacf5\uc744 \uc885\ub8cc\ud558\uac8c \ub41c \uc810 \uc548\ub0b4\ub4dc\ub9bd\ub2c8\ub2e4.\\n\\n\\n1. \uc801\uc6a9 \uc77c\uc790  \\n\\n2025\ub144 4\uc6d4 24\uc77c \ubaa9\uc694\uc77c\\n\\n\\n2. \ubcc0\uacbd \uc0ac\ud56d\\n\\n- \uacfc\uac70 \uc804\ud658 \uc131\uacfc \uc870\ud68c \uc751\ub2f5 \uacb0\uacfc \ub0b4 \u2018convPartner\' \ud56d\ubaa9 \uc0ad\uc81c  \\n- \uc2e4\uc2dc\uac04 \uc804\ud658 \uc131\uacfc \uc870\ud68c \uc751\ub2f5 \uacb0\uacfc \ub0b4 \u2018convPartner\' \ud56d\ubaa9 \uc0ad\uc81c\\n\\n[2] \ucea0\ud398\uc778 \uc608\uc0b0 \ub2e4\uc911 \ubcc0\uacbd \'Deprecated\' \ucc98\ub9ac\\n\\n\u2018\ucea0\ud398\uc778 \uc9c0\ucd9c \ud55c\ub3c4 \ub2e4\uc911 \ubcc0\uacbd\u2019 API\ub85c \ub300\uccb4\ub41c \uc774\ud6c4 \uc77c\uc815 \uae30\uac04 \uc720\uc9c0\ub418\uc5b4\uc654\ub358  \\n\u2018\ucea0\ud398\uc778 \uc608\uc0b0 \ub2e4\uc911 \ubcc0\uacbd\u2019 API\ub294 Deprecated \ucc98\ub9ac\ub420 \uc608\uc815\uc785\ub2c8\ub2e4.  \\n\uc55e\uc73c\ub85c\ub294 \u2018\ucea0\ud398\uc778 \uc9c0\ucd9c \ud55c\ub3c4 \ub2e4\uc911 \ubcc0\uacbd\u2019 API\ub97c \uc774\uc6a9\ud574 \uc8fc\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.\\n\\n1. \uc801\uc6a9 \uc77c\uc790  \\n\\n2025\ub144 4\uc6d4 24\uc77c \ubaa9\uc694\uc77c\\n\\n\\n2. \ubcc0\uacbd \uc0ac\ud56d\\n\\n- \ucea0\ud398\uc778 \uc608\uc0b0 \ub2e4\uc911 \ubcc0\uacbd \u2018Deprecated\' \ucc98\ub9ac\\n\\n\\n\uae30\ud0c0 \uad81\uae08\ud558\uc2e0 \uc0ac\ud56d\uc740 [\ub124\uc774\ubc84 \uc131\uacfc\ud615 \ub514\uc2a4\ud50c\ub808\uc774 \uad11\uace0 API \ubb38\uc758](https://gfa.naver.com/loginAccount/qna)\ub97c \uc774\uc6a9\ud574 \uc8fc\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.\\n\\n\uac10\uc0ac\ud569\ub2c8\ub2e4."},{"id":"2025-03-14-update","metadata":{"permalink":"/openapi-guide/blog/2025-03-14-update","source":"@site/blog/2025-03-14-update/index.md","title":"2025\ub144 3\uc6d4 \ud50c\ub7ab\ud3fc \ubcc0\uacbd \uc0ac\ud56d \uc548\ub0b4 (3\uc6d4 14\uc77c \uc5c5\ub370\uc774\ud2b8)","description":"\uc548\ub155\ud558\uc138\uc694. \ub124\uc774\ubc84 \uc131\uacfc\ud615 \ub514\uc2a4\ud50c\ub808\uc774 \uad11\uace0 \uc6b4\uc601\uc790\uc785\ub2c8\ub2e4.","date":"2025-03-14T00:00:00.000Z","formattedDate":"2025\ub144 3\uc6d4 14\uc77c","tags":[{"label":"patch","permalink":"/openapi-guide/blog/tags/patch"}],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"2025-03-14-update","title":"2025\ub144 3\uc6d4 \ud50c\ub7ab\ud3fc \ubcc0\uacbd \uc0ac\ud56d \uc548\ub0b4 (3\uc6d4 14\uc77c \uc5c5\ub370\uc774\ud2b8)","tags":["patch"]},"prevItem":{"title":"2025\ub144 4\uc6d4 \ud50c\ub7ab\ud3fc \ubcc0\uacbd \uc0ac\ud56d \uc548\ub0b4 (4\uc6d4 24\uc77c \uc5c5\ub370\uc774\ud2b8)","permalink":"/openapi-guide/blog/2025-04-24-update"},"nextItem":{"title":"2024\ub144 9\uc6d4 \ud50c\ub7ab\ud3fc \ubcc0\uacbd \uc0ac\ud56d \uc548\ub0b4 (9\uc6d4 26\uc77c \uc5c5\ub370\uc774\ud2b8)","permalink":"/openapi-guide/blog/2024-09-26-update"}},"content":"\uc548\ub155\ud558\uc138\uc694. \ub124\uc774\ubc84 \uc131\uacfc\ud615 \ub514\uc2a4\ud50c\ub808\uc774 \uad11\uace0 \uc6b4\uc601\uc790\uc785\ub2c8\ub2e4.\\n\\n2025\ub144 3\uc6d4 \ub124\uc774\ubc84 \uc131\uacfc\ud615 \ub514\uc2a4\ud50c\ub808\uc774 \uad11\uace0 \ud50c\ub7ab\ud3fc \ubcc0\uacbd \uc0ac\ud56d \uc548\ub0b4\ub4dc\ub9bd\ub2c8\ub2e4.\\n\uc790\uc138\ud55c \uc0ac\ud56d\uc740 \uc544\ub798 \ub0b4\uc6a9\uc744 \ucc38\uace0\ud558\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.\u200b\\n\\n**\u25a0 \ubcc0\uacbd \uc0ac\ud56d**\\n\\n[1] \uac8c\uc7ac \uc704\uce58 \uac1c\ud3b8\u200b\\n\\n**\u25a0 \uc0c1\uc138 \ubcc0\uacbd \ub0b4\uc6a9**\\n\\n[1] \uac8c\uc7ac \uc704\uce58 \uac1c\ud3b8\\n\\n\uad11\uace0\uc758 \uac8c\uc7ac \uc704\uce58\ub97c \uc790\ub3d9\uc73c\ub85c \ucd5c\uc801\ud654\ud558\uae30 \uc704\ud574 \u2018\ub124\uc774\ubc84\u2019 \ubc0f \u2018\ub124\uc774\ubc84 \ud328\ubc00\ub9ac \ub9e4\uccb4\u2019\uc758 \uac8c\uc7ac \uc704\uce58\ub97c \u2018\ub124\uc774\ubc84+\u2019\ub85c \ud1b5\ud569\ud558\uc5ec \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n**\uc801\uc6a9 \uc77c\uc790**\\n\\n2025\ub144 3\uc6d4 14\uc77c(\uae08)\\n\\n**\ubcc0\uacbd \uc0ac\ud56d**\\n\\n\u2018\ub124\uc774\ubc84\u2019 \ubc0f \u2018\ub124\uc774\ubc84 \ud328\ubc00\ub9ac \ub9e4\uccb4\u2019 \ub0b4 \uac8c\uc7ac \uc704\uce58\uac00 \u2018\ub124\uc774\ubc84+\u2019\ub85c \ud1b5\ud569\ub428\uc5d0 \ub530\ub77c,\\n\ub354 \uc774\uc0c1 \'\ub124\uc774\ubc84 \ud328\ubc00\ub9ac \ub9e4\uccb4\' \uac8c\uc7ac \uc704\uce58 \ucf54\ub4dc(placementGroupCodes)\ub97c \uad11\uace0 \uadf8\ub8f9 \uc0dd\uc131 \ubc0f \uc218\uc815 \uc2dc \uc0ac\uc6a9\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n| \uac12 | \ub0b4\uc6a9 |\\n|--|--|\\n| (Deprecated) BAND | \ub124\uc774\ubc84 \ud328\ubc00\ub9ac \ub9e4\uccb4 > \ud53c\ub4dc \uc601\uc5ed | \\n| (Deprecated) F_BANNER | \ub124\uc774\ubc84 \ud328\ubc00\ub9ac \ub9e4\uccb4 > \ubc30\ub108 \uc601\uc5ed | \\n| (Deprecated) F_SMARTCHANNEL | \ub124\uc774\ubc84 \ud328\ubc00\ub9ac \ub9e4\uccb4 > \uc2a4\ub9c8\ud2b8\ucc44\ub110 | \\n\\n- \uc624\ud508 API > \uc804\uccb4 \ud0c0\uc785 > PlacementGroup\\n- \uad11\uace0 API > \uad11\uace0 \uadf8\ub8f9 > \uad11\uace0 \uadf8\ub8f9 \ubaa9\ub85d > placementGroupCodes\\n- \uad11\uace0 API > \uad11\uace0 \uadf8\ub8f9 > \uad11\uace0 \uadf8\ub8f9 \ub9cc\ub4e4\uae30 > placementGroupCodes\\n- \uad11\uace0 API > \uad11\uace0 \uadf8\ub8f9 > \uad11\uace0 \uadf8\ub8f9 \ub514\ubc14\uc774\uc2a4 \ubc0f \uac8c\uc7ac \uc704\uce58 \ubcc0\uacbd > placementGroupCodes\\n\\n\uae30\ud0c0 \uad81\uae08\ud558\uc2e0 \uc0ac\ud56d\uc740 \ub124\uc774\ubc84 \uc131\uacfc\ud615 \ub514\uc2a4\ud50c\ub808\uc774 \uad11\uace0 API \ubb38\uc758\ub97c \uc774\uc6a9\ud574 \uc8fc\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.\\n\\n\uac10\uc0ac\ud569\ub2c8\ub2e4."},{"id":"2024-09-26-update","metadata":{"permalink":"/openapi-guide/blog/2024-09-26-update","source":"@site/blog/2024-09-26-update/index.md","title":"2024\ub144 9\uc6d4 \ud50c\ub7ab\ud3fc \ubcc0\uacbd \uc0ac\ud56d \uc548\ub0b4 (9\uc6d4 26\uc77c \uc5c5\ub370\uc774\ud2b8)","description":"\uc548\ub155\ud558\uc138\uc694. \ub124\uc774\ubc84 \uc131\uacfc\ud615 \ub514\uc2a4\ud50c\ub808\uc774 \uad11\uace0 \uc624\ud508 API \uc6b4\uc601\uc790\uc785\ub2c8\ub2e4.","date":"2024-09-26T00:00:00.000Z","formattedDate":"2024\ub144 9\uc6d4 26\uc77c","tags":[{"label":"patch","permalink":"/openapi-guide/blog/tags/patch"}],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"2024-09-26-update","title":"2024\ub144 9\uc6d4 \ud50c\ub7ab\ud3fc \ubcc0\uacbd \uc0ac\ud56d \uc548\ub0b4 (9\uc6d4 26\uc77c \uc5c5\ub370\uc774\ud2b8)","tags":["patch"]},"prevItem":{"title":"2025\ub144 3\uc6d4 \ud50c\ub7ab\ud3fc \ubcc0\uacbd \uc0ac\ud56d \uc548\ub0b4 (3\uc6d4 14\uc77c \uc5c5\ub370\uc774\ud2b8)","permalink":"/openapi-guide/blog/2025-03-14-update"},"nextItem":{"title":"\ud658\uc601\ud569\ub2c8\ub2e4.","permalink":"/openapi-guide/blog/welcome"}},"content":"\uc548\ub155\ud558\uc138\uc694. \ub124\uc774\ubc84 \uc131\uacfc\ud615 \ub514\uc2a4\ud50c\ub808\uc774 \uad11\uace0 \uc624\ud508 API \uc6b4\uc601\uc790\uc785\ub2c8\ub2e4.\\n\\n2024\ub144 9\uc6d4 \ub124\uc774\ubc84 \uc131\uacfc\ud615 \ub514\uc2a4\ud50c\ub808\uc774 \uad11\uace0 \ud50c\ub7ab\ud3fc \ubcc0\uacbd \uc0ac\ud56d \uc548\ub0b4\ub4dc\ub9bd\ub2c8\ub2e4.\\n\\n\uc790\uc138\ud55c \uc0ac\ud56d\uc740 \uc544\ub798 \ub0b4\uc6a9\uc744 \ucc38\uace0\ud558\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.\\n\\n\\n\u25a0 \ubcc0\uacbd \uc0ac\ud56d\\n\\n[1] \uc624\ud508 API \uc5f0\ub3d9 \ubc29\uc2dd \ubcc0\uacbd\\n\\n\u25a0 \uc0c1\uc138 \ubcc0\uacbd \ub0b4\uc6a9\\n\\n[1] \ubcc0\uacbd \uc0ac\ud56d \uc81c\ubaa9\\n\\n\uc624\ud508 API > \uad11\uace0 \uad00\ub9ac > \uad11\uace0 \uc18c\uc7ac > \uad11\uace0 \uc18c\uc7ac \ubaa9\ub85d API \ub0b4 \ud30c\ub77c\ubbf8\ud130/\uc751\ub2f5 \ubcc0\uacbd\\n\\n- \uc801\uc6a9 \uc77c\uc790\\n\\n  2024\ub144 9\uc6d4 26\uc77c \ubaa9\uc694\uc77c\\n\\n- \ubcc0\uacbd \uc0ac\ud56d\\n  - \uad11\uace0 \uc18c\uc7ac \ubaa9\ub85d API \uc870\ud68c \uc2dc \u2018campaignNo\u2019 \ud56d\ubaa9 \uc0ad\uc81c\\n  - \uad11\uace0 \uc18c\uc7ac \ubaa9\ub85d API \uc751\ub2f5 \ub0b4 \'adSetName\u2019, \u2018campaignName\u2019, \u2018campaignNo\' \ud56d\ubaa9 \uc81c\uac70\\n\\n\uae30\ud0c0 \uad81\uae08\ud558\uc2e0 \uc0ac\ud56d\uc740 \ub124\uc774\ubc84 \uc131\uacfc\ud615 \ub514\uc2a4\ud50c\ub808\uc774 \uad11\uace0 API \ubb38\uc758\ub97c \uc774\uc6a9\ud574 \uc8fc\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.\\n\uac10\uc0ac\ud569\ub2c8\ub2e4."},{"id":"welcome","metadata":{"permalink":"/openapi-guide/blog/welcome","source":"@site/blog/2023-02-03-welcome/index.md","title":"\ud658\uc601\ud569\ub2c8\ub2e4.","description":"\ud658\uc601\ud569\ub2c8\ub2e4.","date":"2023-02-03T00:00:00.000Z","formattedDate":"2023\ub144 2\uc6d4 3\uc77c","tags":[{"label":"hello","permalink":"/openapi-guide/blog/tags/hello"}],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"welcome","title":"\ud658\uc601\ud569\ub2c8\ub2e4.","tags":["hello"]},"prevItem":{"title":"2024\ub144 9\uc6d4 \ud50c\ub7ab\ud3fc \ubcc0\uacbd \uc0ac\ud56d \uc548\ub0b4 (9\uc6d4 26\uc77c \uc5c5\ub370\uc774\ud2b8)","permalink":"/openapi-guide/blog/2024-09-26-update"}},"content":"\ud658\uc601\ud569\ub2c8\ub2e4.\\n\\n\uc774 \ud398\uc774\uc9c0\ub97c \ud1b5\ud574 \uacf5\uc9c0 \uc0ac\ud56d\uc744 \uc804\ub2ec\ud560 \uc608\uc815\uc785\ub2c8\ub2e4.\\n\\n![Docusaurus Plushie](./docusaurus-plushie-banner.jpeg)"}]}')}}]);